// Actual std Map/Set Extend/FromIterator dispatch and owned iterator cleanup.
use rustc_hash::{FxHashMap,FxHashSet};
use std::{cell::RefCell,collections::VecDeque,hash::{Hash,Hasher},io::{self,BufRead,Write},panic::{catch_unwind,AssertUnwindSafe}};
#[derive(Default)]struct Control{events:Vec<String>,count:usize,fail:i64,fired:bool,enabled:bool}
thread_local!{static CONTROL:RefCell<Control>=RefCell::new(Control::default());}
fn event(name:&str,id:u64){let panic=CONTROL.with(|c|{let mut c=c.borrow_mut();if !c.enabled{return None};c.events.push(format!("{name}:{id}:{}",std::thread::panicking()));let n=c.count;c.count+=1;if n as i64==c.fail&&!c.fired{c.fired=true;Some(n)}else{None}});if let Some(n)=panic{std::panic::panic_any(n)}}
struct Key{id:u64,token:u64}impl Hash for Key{fn hash<H:Hasher>(&self,h:&mut H){event("hash",self.token);h.write_u64(self.id)}}impl PartialEq for Key{fn eq(&self,o:&Self)->bool{event("eq",self.token*1000+o.token);self.id==o.id}}impl Eq for Key{}impl Drop for Key{fn drop(&mut self){event("kdrop",self.token)}}
struct Value(u64);impl Drop for Value{fn drop(&mut self){event("vdrop",self.0)}}
struct Plain<T>{values:VecDeque<T>}
impl<T>Iterator for Plain<T>{type Item=T;fn next(&mut self)->Option<T>{event("next",self.values.len()as u64);self.values.pop_front()}fn size_hint(&self)->(usize,Option<usize>){event("hint",self.values.len()as u64);(self.values.len(),Some(self.values.len()))}}
impl<T>Drop for Plain<T>{fn drop(&mut self){event("iterdrop",self.values.len()as u64)}}
struct Foreach<T>(Plain<T>);impl<T>Iterator for Foreach<T>{type Item=T;fn next(&mut self)->Option<T>{self.0.next()}fn size_hint(&self)->(usize,Option<usize>){self.0.size_hint()}fn for_each<F:FnMut(T)>(mut self,mut f:F){event("foreach",0);while let Some(v)=self.0.values.pop_back(){f(v)}}}
struct Fold<T>(Plain<T>);impl<T>Iterator for Fold<T>{type Item=T;fn next(&mut self)->Option<T>{self.0.next()}fn size_hint(&self)->(usize,Option<usize>){self.0.size_hint()}fn fold<B,F:FnMut(B,T)->B>(mut self,mut a:B,mut f:F)->B{event("fold",0);while let Some(v)=self.0.values.pop_front(){a=f(a,v)}a}}
struct Both<T>(Plain<T>);impl<T>Iterator for Both<T>{type Item=T;fn next(&mut self)->Option<T>{self.0.next()}fn size_hint(&self)->(usize,Option<usize>){self.0.size_hint()}fn for_each<F:FnMut(T)>(mut self,mut f:F){event("foreach",0);while let Some(v)=self.0.values.pop_back(){f(v)}}fn fold<B,F:FnMut(B,T)->B>(mut self,mut a:B,mut f:F)->B{event("fold",0);while let Some(v)=self.0.values.pop_front(){a=f(a,v)}a}}
struct MapCtor<T>(Plain<T>);impl<T>Iterator for MapCtor<T>{type Item=T;fn next(&mut self)->Option<T>{self.0.next()}fn size_hint(&self)->(usize,Option<usize>){self.0.size_hint()}fn map<B,F:FnMut(T)->B>(mut self,mut f:F)->std::iter::Map<Self,F>{event("map_ctor",0);if let Some(value)=self.next(){drop(f(value))}panic!("map_ctor")}}
struct Input<I>{iterator:Option<I>}
impl<I>Drop for Input<I>{fn drop(&mut self){event("inputdrop",0)}}
impl<I:Iterator>IntoIterator for Input<I>{type Item=I::Item;type IntoIter=I;fn into_iter(mut self)->I{event("into",0);self.iterator.take().unwrap()}}
fn outcome(r:Result<(),Box<dyn std::any::Any+Send>>)->String{match r{Ok(())=>"ok".into(),Err(p)=>if let Some(n)=p.downcast_ref::<usize>(){format!("event:{n}")}else if p.downcast_ref::<&str>()==Some(&"map_ctor"){"ctor".into()}else{panic!("unexpected panic payload")}}}
fn map_run<I:Iterator<Item=(Key,Value)>>(iterator:I,from:bool)->(String,String,String){let mut map=if from{None}else{Some({let mut m=FxHashMap::default();m.insert(Key{id:99,token:99},Value(199));m})};CONTROL.with(|c|{let mut c=c.borrow_mut();c.enabled=true;c.count=0;c.events.clear()});let action=catch_unwind(AssertUnwindSafe(||{let input=Input{iterator:Some(iterator)};if from{map=Some(FxHashMap::from_iter(input))}else{map.as_mut().unwrap().extend(input)}}));let snapshot=map.as_ref().map(|m|{let mut s=format!("{}:",m.len());for(k,v)in m{s.push_str(&format!("{}/{}/{},",k.id,k.token,v.0));}s}).unwrap_or("none".into());CONTROL.with(|c|c.borrow_mut().events.push("final".into()));let final_drop=catch_unwind(AssertUnwindSafe(||drop(map.take())));(outcome(action),outcome(final_drop),snapshot)}
fn set_run<I:Iterator<Item=Key>>(iterator:I,from:bool)->(String,String,String){let mut set=if from{None}else{Some({let mut s=FxHashSet::default();s.insert(Key{id:99,token:99});s})};CONTROL.with(|c|{let mut c=c.borrow_mut();c.enabled=true;c.count=0;c.events.clear()});let action=catch_unwind(AssertUnwindSafe(||{let input=Input{iterator:Some(iterator)};if from{set=Some(FxHashSet::from_iter(input))}else{set.as_mut().unwrap().extend(input)}}));let snapshot=set.as_ref().map(|m|{let mut s=format!("{}:",m.len());for k in m{s.push_str(&format!("{}/{},",k.id,k.token));}s}).unwrap_or("none".into());CONTROL.with(|c|c.borrow_mut().events.push("final".into()));let final_drop=catch_unwind(AssertUnwindSafe(||drop(set.take())));(outcome(action),outcome(final_drop),snapshot)}
macro_rules! dispatch{($plain:expr,$vec:expr,$mode:expr,$run:ident,$from:expr)=>{match $mode{0=>$run($plain,$from),1=>$run(Foreach($plain),$from),2=>$run(Fold($plain),$from),3=>$run(Both($plain),$from),4=>$run(MapCtor($plain),$from),5=>$run($vec,$from),_=>panic!("bad mode")}}}
fn hex(s:&str)->String{s.as_bytes().iter().map(|b|format!("{b:02x}")).collect()}
fn main()->io::Result<()>{std::panic::set_hook(Box::new(|_|{}));let mut out=io::BufWriter::new(io::stdout().lock());for line in io::stdin().lock().lines(){let line=line?;let f:Vec<_>=line.split('\t').collect();assert_eq!(f.len(),6);let kind=f[0];let mode:usize=f[1].parse().unwrap();let from=f[2]=="true";let n:usize=f[3].parse().unwrap();let skip=f[4]=="true";let fail=f[5].parse().unwrap();CONTROL.with(|c|*c.borrow_mut()=Control{fail,..Default::default()});let result=if kind=="map"{let values:Vec<_>=(0..n).map(|i|(Key{id:[1,2,1,3][i%4],token:i as u64+11},Value(i as u64+101))).collect();if mode==5{let mut iterator=values.into_iter();if skip{drop(iterator.next())}map_run(iterator,from)}else{let mut plain=Plain{values:values.into()};if skip{drop(plain.next())}dispatch!(plain,std::iter::empty::<(Key,Value)>(),mode,map_run,from)}}else{let values:Vec<_>=(0..n).map(|i|Key{id:[1,2,1,3][i%4],token:i as u64+11}).collect();if mode==5{let mut iterator=values.into_iter();if skip{drop(iterator.next())}set_run(iterator,from)}else{let mut plain=Plain{values:values.into()};if skip{drop(plain.next())}dispatch!(plain,std::iter::empty::<Key>(),mode,set_run,from)}};let(counter,events)=CONTROL.with(|c|{let c=c.borrow();(c.count,c.events.join("|"))});writeln!(out,"{line}\t{}\t{}\t{counter}\t{}\t{}",result.0,result.1,hex(&result.2),hex(&events))?;}Ok(())}
